cn_ban_10:[A("hh","Trung cung mở phiên xét lại án chị em cũ của {me}. {Me} xuất thân kẻ hầu, nói ra không ai nghe. Xin {call} đứng cạnh {me} một lời trước Hoàng hậu.",
  "Đứng ra nói một lời trước Hoàng hậu","Hoàng hậu cho là ngươi lấy danh mình bảo lãnh tội nô","Dâng lễ Khôn Ninh cung xin xét cho công bằng","lễ bị cho là đút lót phiên xét"),
 A("do","Phiên xét lại án sắp mở, mà người của {B} đã đến gặp nhân chứng trước. {Call} giúp {me} xem họ đã nói gì với người ấy.",
  "Sai người hỏi nhân chứng sau khi người của {B} đi","người của ngươi bị coi là đi ép nhân chứng","Tự gặp nhân chứng hỏi chuyện","{B} biết ngươi đã gặp nhân chứng")],
